/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
for p in sorted(Path('.').glob('pc*/etc/bind/db.*')):
 print(p, ':', ' | '.join(p.read_text().splitlines()))
for p in Path('.').glob('*.startup'):
 if p.name.startswith('pc'):
  assert 'nameserver 10.14.5.13' in p.read_text()
for p in Path('.').glob('pc*/etc/bind/named.conf'):
 assert 'dnssec-validation no' in p.read_text()
print('Static DNS and client checks passed')
PY
for f in *.startup; do bash -n \""'$f" || exit 1; done'

